const allowed=new Set(['text','note','rect','ellipse','line','arrow','highlight','redact','image','draw']);
export function validateProject(data){
const fail=()=>{throw Error('Proje dosyası geçersiz veya desteklenmeyen içerik taşıyor.');};
if(data.version!==1||!data.state||!Array.isArray(data.state.pages)||!data.sources||typeof data.sources!=='object')fail();
if(data.state.pages.length>500||Object.keys(data.sources).length>500||typeof data.state.title!=='string'||data.state.title.length>500)fail();
let count=0;for(const p of data.state.pages){if(typeof p.id!=='string'||!Number.isFinite(p.w)||!Number.isFinite(p.h)||p.w<=0||p.h<=0||p.w>14400||p.h>14400||![0,90,180,270].includes(p.rotation)||!Array.isArray(p.objects)||!Array.isArray(p.removed))fail();if(p.sourceId&&(!data.sources[p.sourceId]||!Number.isInteger(p.index)||p.index<0))fail();
for(const r of p.removed){if(!['text','image','redact'].includes(r.kind)||!Array.isArray(r.rect)||r.rect.length!==4||!r.rect.every(Number.isFinite))fail();}
for(const o of p.objects){if(o.fontMode!==undefined&&!['original','noto'].includes(o.fontMode))fail();if(o.nativeFont){const f=o.nativeFont;if(o.type!=='text'||typeof f!=='object')fail();if(f.upload){if(typeof f.upload.id!=='string'||!/^[-\w]+$/.test(f.upload.id)||typeof f.upload.name!=='string'||f.upload.name.length>300||typeof f.upload.data!=='string'||f.upload.data.length>17*1024*1024||!/^[a-z\d+/=]+$/i.test(f.upload.data))fail();}else if(!data.sources[f.sourceId]||!Number.isInteger(f.index)||f.index<0||!/^font-\d+$/.test(f.key)||typeof f.name!=='string')fail();}if(++count>50000||!allowed.has(o.type)||typeof o.id!=='string'||!/^[\w-]+$/.test(o.id)||!['x','y','w','h'].every(k=>Number.isFinite(o[k])&&Math.abs(o[k])<100000)||(o.w<0||o.h<0||((o.w===0||o.h===0)&&!['line','arrow'].includes(o.type))||(o.w===0&&o.h===0))||!/^#[a-f\d]{6}$/i.test(o.color)||!Number.isFinite(o.opacity)||o.opacity<0||o.opacity>1)fail();if(o.angle!==undefined&&!Number.isFinite(o.angle))fail();if(o.size!==undefined&&(!Number.isFinite(o.size)||o.size<1||o.size>1000))fail();if(o.stroke!==undefined&&(!Number.isFinite(o.stroke)||o.stroke<0||o.stroke>100))fail();if(o.align!==undefined&&!['left','center','right'].includes(o.align))fail();if(['text','note'].includes(o.type)&&(typeof o.text!=='string'||o.text.length>100000))fail();if(o.type==='image'&&(typeof o.src!=='string'||!/^data:image\/(png|jpeg);base64,[a-z\d+/=]+$/i.test(o.src)))fail();if(o.type==='draw'&&(!Array.isArray(o.points)||o.points.length>100000||!o.points.every(p=>p.length===2&&p.every(Number.isFinite))))fail();}}
return data;
}
